function out=finalize_ScaleSem_visuals_R2019a()
here=fileparts(mfilename('fullpath'));od=fullfile(here,'ScaleSem_four_method_visuals');pd=fullfile(od,'partials');
names={'COIL20','PIE','YaleB'};methods={'ScaleSem-NMF','HLPNMF','GOCNMF','SNMFWLP'};rows=cell(36,5);rr=0;
fig=figure('Color','w','Position',[60 40 1500 900]);ax=zeros(3,4);
for d=1:3,for z=1:3,S=load(fullfile(pd,sprintf('d%d_z%d.mat',d,z)));for m=1:4,rr=rr+1;rows(rr,:)={names{d},methods{m},S.pseeds(z),S.purity(m),numel(S.labels)};if z==1,ax(d,m)=subplot(3,4,(d-1)*4+m);scatter(S.Z{m}(:,1),S.Z{m}(:,2),9,S.labels,'filled','MarkerFaceAlpha',.68,'MarkerEdgeColor','none');axis tight;grid on;set(gca,'XTick',[],'YTick',[]);colormap(gca,lines(max(S.labels)));title(sprintf('%s: %s',names{d},methods{m}),'FontWeight','normal');end;end;end;end
left=.035;right=.99;bottom=.045;top=.97;hgap=.025;vgap=.065;w=(right-left-3*hgap)/4;h=(top-bottom-2*vgap)/3;for d=1:3,for m=1:4,set(ax(d,m),'Position',[left+(m-1)*(w+hgap),top-d*h-(d-1)*vgap,w,h]);end;end
set(findall(fig,'Type','axes'),'FontName','Times New Roman','FontSize',9,'Box','on');
rp=fullfile(od,'four-method-tsne.png');rf=fullfile(od,'four-method-tsne.pdf');print(fig,rp,'-dpng','-r300');set(fig,'PaperPositionMode','auto');print(fig,rf,'-dpdf','-painters');close(fig);
T=cell2table(rows,'VariableNames',{'dataset','method','projection_seed','knn_purity','n_samples'});writetable(T,fullfile(od,'tsne-stability.csv'));
root='E:\codex\2026-10-03\referenced-chatgpt-conversation-this-is-an';D=load(fullfile(root,'outputs','PCE_baseline_alignment','data','COIL20.mat'));if isfield(D,'X'),X=double(D.X);else,X=double(D.fea)';end;if isfield(D,'y'),y=double(D.y(:));else,y=double(D.gnd(:));end;if size(X,2)~=numel(y),X=X';end;[~,~,y]=unique(y);nr=sqrt(sum(X.^2,1));nr(nr==0)=1;X=bsxfun(@rdivide,X,nr);
R=load(fullfile(here,'scale_semantic_nmf_psd_l1_iter200_tol1e-07','COIL20_seed20260627.mat'),'U');U=double(R.U);C=max(y);cs=zeros(C,1);for q=1:C,mu=mean(X(:,y==q),2);cs(q)=(U(:,q)'*mu)/max(norm(U(:,q))*norm(mu),eps);end
fig=figure('Color','w','Position',[50 50 1500 850]);for q=1:C,subplot(4,5,q);imagesc(reshape(U(:,q),32,32)');axis image off;colormap(gray(256));title(sprintf('Class %d, cos=%.2f',q,cs(q)),'FontName','Times New Roman','FontSize',9,'FontWeight','normal');end;annotation(fig,'textbox',[.01 .965 .98 .025],'String','COIL20 ScaleSem-NMF basis columns','HorizontalAlignment','center','EdgeColor','none','FontName','Times New Roman','FontSize',12,'FontWeight','bold');bp=fullfile(od,'coil20-basis-prototypes.png');bf=fullfile(od,'coil20-basis-prototypes.pdf');print(fig,bp,'-dpng','-r300');set(fig,'PaperPositionMode','auto');print(fig,bf,'-dpdf','-painters');close(fig);BT=table((1:C)',cs,'VariableNames',{'class','cosine_to_class_mean'});writetable(BT,fullfile(od,'coil20-basis-similarity.csv'));out=struct('representation_png',rp,'basis_png',bp,'stability',T,'basis_similarity',BT);fprintf('FINALIZED %s\n',od);
end
